style.css:
/* Chrome Extension CSS - Baby Pink Text */
* {
  color: #E75480 !important;
}

/* Target specific elements for better coverage */
p, span, div, h1, h2, h3, h4, h5, h6, li, td, th, label, input, textarea, select, button, a {
  color: #E75480 !important;
}

/* Force override for stubborn elements */
*:not(script):not(style):not(meta):not(title):not(link) {
  color: #E75480 !important;
}
